MOD = 1000000007

def dfs(node, parent, graph, visited, cycle):
    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            if dfs(neighbor, node, graph, visited, cycle):
                return True
        elif neighbor != parent:
            cycle.add(node)
            return True
    return False

def find_cycles(graph, n):
    visited = [False] * (n + 1)
    cycle = set()
    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, graph, visited, cycle)
    return cycle

